use std::env
use std::fs
use std::io

fn pad6(n: int) -> string {
    let s = "${n}"
    let mut out = ""
    let mut i = s.len()
    while i < 6 {
        out = out + " "
        i = i + 1
    }
    out + s
}

fn emit(text: string, number: bool, counter: int) -> int {
    let mut c = counter
    if !number {
        print("${text}")
        return c
    }
    let mut parts: Vec<string> = text.split("\n").collect()
    if parts.len() > 0 && parts[parts.len() - 1] == "" {
        parts.pop()
    }
    for line in parts {
        c = c + 1
        println("${pad6(c)}\t${line}")
    }
    c
}

fn main() {
    let args = env::args()
    let mut number = false
    let mut files: Vec<string> = Vec::new()
    let mut idx = 0
    for a in args {
        idx = idx + 1
        if idx == 1 {
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let s = io::read_to_string().unwrap_or("")
        counter = emit(s, number, counter)
    } else {
        for f in files {
            if !fs::exists(f) {
                println("cat: ${f}: No such file")
                status = 1
            } else {
                let s = fs::read_to_string(f).unwrap_or("")
                counter = emit(s, number, counter)
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}

